service.method:

DELETE FROM
	SDEPT
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}
	AND DEPT = ${DEPT}


    	SELECT COMPANY_CODE
    	FROM SCMGL
		WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
		  AND COMPANY_CODE      = ${COMPANY_CODE}
		  AND DEL_FLAG	   = 'N'


		MERGE INTO SADDR
		USING (SELECT '' A) DUAL ON 
		     (	  HOUSE_CODE   = ${session.HOUSE_CODE}
		  	  AND CODE_NO      = ${CODE_NO}
		  	  AND CODE_TYPE    = ${CODE_TYPE}
		  	 )
		 WHEN MATCHED 
		 THEN UPDATE                                                        
		         SET ADDRESS_LOC  = ${ADDRESS_LOC}                                
			        ,ADDRESS_ENG  = ${ADDRESS_ENG}                               
			        ,ZIP_CODE     = ${ZIP_CODE}
			        ,HOMEPAGE     = ${HOMEPAGE}
			        ,PHONE_NO1	  = ${PHONE_NO}
			        ,CEO_NAME_LOC = ${CEO_NAME}
			        ,CHANGE_DATE     = ${current.date}      
					,CHANGE_TIME     = ${current.time}
					,CHANGE_USER_ID  = ${session.ID} 
	   	 WHEN NOT MATCHED 
	     THEN INSERT(HOUSE_CODE
	                ,CODE_NO
	                ,CODE_TYPE
	                ,ADDRESS_LOC 
					,ADDRESS_ENG 
					,ZIP_CODE    
					,HOMEPAGE    
					,PHONE_NO1	 
					,CEO_NAME_LOC     
					,CHANGE_DATE    
	                ,CHANGE_TIME    
	                ,CHANGE_USER_ID 
	                ,ADD_DATE   
	                ,ADD_TIME   
	                ,ADD_USER_ID 
	     	)VALUES(
	     	        ${session.HOUSE_CODE}
	     	       ,${CODE_NO}
	     	       ,${CODE_TYPE}
	     	 	   ,${ADDRESS_LOC}
			       ,${ADDRESS_ENG}
			       ,${ZIP_CODE}   
			       ,${HOMEPAGE}   
			       ,${PHONE_NO}   
			       ,${CEO_NAME}
			       ,${current.date}    
                   ,${current.time}    
                   ,${session.ID}
                   ,${current.date}    
                   ,${current.time}    
                   ,${session.ID}
	     	);


		MERGE INTO SCMGL
		USING (SELECT '' A) DUAL ON 
		     (	  HOUSE_CODE   = ${session.HOUSE_CODE}
		  	  AND COMPANY_CODE = ${COMPANY_CODE}
		  	 )
		 WHEN MATCHED 
		 THEN UPDATE                                                        
		         SET LANGUAGE 	 	            = ${LANGUAGE}
					,COMPANY_NAME_LOC           = ${COMPANY_NAME_LOC}      
					,COMPANY_NAME_ENG           = ${COMPANY_NAME_ENG}      
					,CUR                        = ${CUR}      
					,COUNTRY                    = ${COUNTRY}      
					,CITY_CODE                  = ${CITY_CODE}      
					,IRS_NO                     = ${IRS_NO}      
					,DUNS_NO                    = ${DUNS_NO}      
					,FOUNDATION_DATE            = ${FOUNDATION_DATE}      
					,GROUP_COMPANY_CODE         = ${GROUP_COMPANY_CODE}      
					,GROUP_COMPANY_NAME         = ${GROUP_COMPANY_NAME}      
					,CREDIT_RATING              = ${CREDIT_RATING}      
					,INDUSTRY_TYPE              = ${INDUSTRY_TYPE}        
					,BUSINESS_TYPE              = ${BUSINESS_TYPE}      
					,TRADE_AGENCY_NO            = ${TRADE_AGENCY_NO}      
					,TRADE_AGENCY_NAME          = ${TRADE_AGENCY_NAME}      
					,EDI_ID                     = ${EDI_ID}      
					,EDI_QUALIFIER              = ${EDI_QUALIFIER}      
					,INS_COM_CODE               = ${INS_COM_CODE}   
					,CHANGE_DATE     = ${current.date}      
					,CHANGE_TIME     = ${current.time}
					,CHANGE_USER_ID  = ${session.ID}   
					,DEL_FLAG		 = 'N'
					,ATTACH_NO		 = ${ATTACH_NO}  
	   	 WHEN NOT MATCHED 
	     THEN INSERT(HOUSE_CODE
	                ,COMPANY_CODE
	                ,LANGUAGE 	 	   
			        ,COMPANY_NAME_LOC  
			        ,COMPANY_NAME_ENG  
			        ,CUR               
			        ,COUNTRY           
			        ,CITY_CODE         
			        ,IRS_NO            
			        ,DUNS_NO           
			        ,FOUNDATION_DATE   
			        ,GROUP_COMPANY_CODE
			        ,GROUP_COMPANY_NAME
			        ,CREDIT_RATING     
			        ,INDUSTRY_TYPE     
			        ,BUSINESS_TYPE     
			        ,TRADE_AGENCY_NO   
			        ,TRADE_AGENCY_NAME 
			        ,EDI_ID            
			        ,EDI_QUALIFIER     
			        ,INS_COM_CODE
			        ,CHANGE_DATE    
	                ,CHANGE_TIME    
	                ,CHANGE_USER_ID 
	                ,ADD_DATE   
	                ,ADD_TIME   
	                ,ADD_USER_ID
	                ,DEL_FLAG    
	                ,ATTACH_NO   
     		    )
   		    	VALUES
     		    (
	     	        ${session.HOUSE_CODE}
	     	       ,${COMPANY_CODE}
	     		   ,${LANGUAGE}          
			       ,${COMPANY_NAME_LOC}  
			       ,${COMPANY_NAME_ENG}  
			       ,${CUR}               
			       ,${COUNTRY}           
			       ,${CITY_CODE}         
			       ,${IRS_NO}            
			       ,${DUNS_NO}           
			       ,${FOUNDATION_DATE}   
			       ,${GROUP_COMPANY_CODE}
			       ,${GROUP_COMPANY_NAME}
			       ,${CREDIT_RATING}     
			       ,${INDUSTRY_TYPE}     
			       ,${BUSINESS_TYPE}     
			       ,${TRADE_AGENCY_NO}   
			       ,${TRADE_AGENCY_NAME} 
			       ,${EDI_ID}            
			       ,${EDI_QUALIFIER}     
			       ,${INS_COM_CODE}   
			       ,${current.date}    
                   ,${current.time}
                   ,${session.ID}
                   ,${current.date}    
                   ,${current.time}    
                   ,${session.ID}   
                   ,'N'
                   ,${ATTACH_NO}  
	     	);


DELETE FROM SADDR
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND CODE_NO   = ${CODE_NO}
   AND CODE_TYPE = ${CODE_TYPE}


DELETE FROM SCMGL
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}


    	SELECT COMPANY_CODE
    	FROM SCMGL
		WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
		  AND COMPANY_CODE      = ${COMPANY_CODE}
		  AND DEL_FLAG	   = 'N'


    	SELECT DEPT
    	FROM SDEPT
		WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
		  AND DEPT      = ${DEPT_CODE}


SELECT COMPANY_CODE
      ,COMPANY_NAME_LOC
  FROM SCMGL
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE}
   AND COMPANY_CODE     = $S{COMPANY_CODE}
   AND (    1=1
   		AND COMPANY_NAME_LOC LIKE '%' + $S{F_KEYWORD} + '%'
   		 OR COMPANY_CODE     LIKE '%' + $S{F_KEYWORD} + '%'
   )
   AND DEL_FLAG = 'N'


DELETE FROM
	SBAGL
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}
	AND CTRL_CODE = ${CTRL_CODE}
	AND CTRL_NUMBER = ${CTRL_NUMBER}


UPDATE SBALN SET
	COMPANY_CODE = ${COMPANY_CODE},
	CTRL_CODE = ${CTRL_CODE},
	CTRL_PERSON_ID = ${CTRL_PERSON_ID},
	REPRESENT_CTRL = ${REPRESENT_CTRL},
 	CHANGE_DATE     = ${current.date},
 	CHANGE_TIME     = ${current.time},
 	CHANGE_USER_ID  = ${session.ID},
 	APP_ORDER		= ${APP_ORDER}
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND CTRL_CODE = ${CTRL_CODE}
	AND CTRL_PERSON_ID = ${CTRL_PERSON_ID}


DELETE FROM
	SBALN
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}
	AND CTRL_CODE = ${CTRL_CODE}
	AND CTRL_PERSON_ID = ${CTRL_PERSON_ID}


SELECT 
	COUNT(*) AS CNT
FROM SUSMT 
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
  AND COMPANY_CODE = ${session.COMPANY_CODE}
  AND USER_ID = ${PERSON_ID}
  AND DEL_FLAG ='N'


    	SELECT DEPT
    	FROM SDEPT
		WHERE
			HOUSE_CODE	= ${session.HOUSE_CODE}
		AND DEPT		= ${DEPT}


	INSERT 
	  INTO #DB_OWNER#SCODE
         ( HOUSE_CODE
         , TYPE
         , CODE
         , LANGUAGE
         , ADD_DATE
         , ADD_TIME
         , ADD_USER_ID
         , CHANGE_DATE
         , CHANGE_TIME
         , CHANGE_USER_ID
         , FLAG
         , SORT_SEQ
         , USE_FLAG
         , TEXT1
         , DEL_FLAG  
         )
   VALUES( 
           ${session.HOUSE_CODE}
         , 'UX049'
         , ${POSITION}
         , 'KO'
         , ${current.DATE}
         , ${current.TIME}
         , ${session.ID}
         , ${current.DATE}
         , ${current.TIME}
         , ${session.ID}
         , ${FLAG}
         , #{SORT}
         , 'Y'
         , ${POSITION_NAME}
         , 'N'  
       )


DELETE
FROM SCODE
WHERE 
	HOUSE_CODE = ${session.HOUSE_CODE}
AND TYPE = 'UX049'
AND TEXT1 = ${POSITION_NAME}
